"""补丁引擎（monitor_kit/patcher.py）的回归测试。

真实事故：2026-11-06 07:55 那次链启动，`BAAH/main.py` 被补丁写成这样：

    ...
        input("Error, Enter to exit/错误，回车退出:")
    # >>> AFK-MONITOR:baah-error-exit (auto-generated by Auto-AFK; do not edit)
            sys.exit(1)
    # <<< AFK-MONITOR:baah-error-exit
    re_process                      <- 半截垃圾，后面又重复了一整段旧代码

`IndentationError: unexpected indent (main.py, line 52)`，BAAH 直接起不来，
用户点「启动」只看到卡片变成「失败」。两个根因：

1. `_write()` 用 `open(path, "w")` 先把文件截断到 0 再写 —— 更新线程（revert →
   git pull → apply）和手工 apply/verify 同时在跑时，另一路读到的就是半截
   文件，再基于半截内容 apply 写回，结果就是「新前半段 + 旧尾部」。
2. 补丁块一律用 "\\n" 拼行尾、`_find_block` 也只吃 1 个字符的行尾，插进
   CRLF 文件后行尾混乱，`sys.exit(1)` 这类插入点算错一位就毁掉缩进。

判据（这四条各自对应上面的一条根因，任一回归都会让本测试失败）：
1. 打补丁后文件仍然能编译（语法守卫）；
2. 打补丁 → 还原，文件字节完全回到原样（含 CRLF 文件）；
3. apply 幂等：连打三次内容不变、状态是 unchanged；
4. 写入是原子的：落盘后没有残留的 `.afk-tmp`，且写入失败不会留下空文件；
5. 语法守卫会拦住会毁掉文件的补丁，且**不落盘**。
"""

import importlib.util
import shutil
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

FAILED = []


def check(name, ok, detail=""):
    print(("PASS " if ok else "FAIL ") + name + ("" if ok else "  <- " + str(detail)))
    if not ok:
        FAILED.append(name)


def _patcher():
    spec = importlib.util.spec_from_file_location("afk_patcher_smoke", ROOT / "monitor_kit" / "patcher.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


# 一份「成品」的最小样本：函数体、except 尾、缩进都对，用来模拟真实项目文件
SAMPLE = (
    "import sys\n"
    "import os\n"
    "\n"
    "\n"
    "def run_baah_script(config_name):\n"
    "    try:\n"
    "        print('work')\n"
    "        do_work()\n"
    "    \n"
    "    except Exception as e:\n"
    "        import traceback\n"
    "        traceback.print_exc()\n"
    '        input("Error, Enter to exit/错误，回车退出:")\n'
)

BLOCK = {
    "id": "smoke-error-exit",
    "file": "main.py",
    "anchor": 'input("Error, Enter to exit/错误，回车退出:")',
    "insert": "        sys.exit(1)\n",
}

ENTRY_BLOCK = {
    "id": "smoke-entry",
    "file": "main.py",
    "anchor": "def run_baah_script(config_name):",
    "insert": (
        "    try:\n"
        "        import afk_hook as _afk_hook\n"
        "        _afk_hook.install(project=\"Smoke\")\n"
        "    except Exception:\n"
        "        pass\n"
    ),
}


def _read(path):
    # 必须用 newline="" 才看得到真实行尾；Path.read_text 在 3.11 里没有 newline 参数
    with open(path, "r", encoding="utf-8", newline="") as f:
        return f.read()


def _write(path, text):
    with open(path, "w", encoding="utf-8", newline="") as f:
        f.write(text)


def _compile_ok(text, label):
    try:
        compile(text, label, "exec")
        return True, ""
    except SyntaxError as exc:
        return False, "{0}: {1} (line {2})".format(type(exc).__name__, exc.msg, exc.lineno)


def _roundtrip(module, label, original):
    text = original
    for block in (ENTRY_BLOCK, BLOCK):
        text, _ = module.apply_block(text, block)
    ok, detail = _compile_ok(text, label)
    check("{0}：打完补丁仍能编译".format(label), ok, detail)
    check("{0}：两个补丁块的标记都在".format(label),
          "AFK-MONITOR:smoke-entry" in text and "AFK-MONITOR:smoke-error-exit" in text)
    check("{0}：sys.exit(1) 落在标记块里面".format(label),
          "# >>> AFK-MONITOR:smoke-error-exit" in text
          and text.index("sys.exit(1)") > text.index("# >>> AFK-MONITOR:smoke-error-exit")
          and text.index("sys.exit(1)") < text.index("# <<< AFK-MONITOR:smoke-error-exit"),
          "插入点算错就会像事故那样把缩进毁掉")

    for block in (BLOCK, ENTRY_BLOCK):
        text, state = module.revert_block(text, block)
        check("{0}：还原 {1} 的状态是 reverted".format(label, block["id"]), state == "reverted", state)
    check("{0}：还原后与原文件逐字节一致".format(label), text == original,
          "还原残留会让磁盘文件越改越脏")

    # 幂等：连打三次，第二次起必须是 unchanged 且内容不变
    again = original
    for block in (ENTRY_BLOCK, BLOCK):
        again, _ = module.apply_block(again, block)
    one_shot = again
    for i in range(2):
        for block in (ENTRY_BLOCK, BLOCK):
            again, state = module.apply_block(again, block)
            check("{0}：第 {1} 次重复 apply 是 unchanged".format(label, i + 2), state == "unchanged", state)
    check("{0}：重复 apply 后内容不变".format(label), again == one_shot)

    state = module.verify_block(one_shot, BLOCK)
    check("{0}：verify 认得出补丁在正确位置".format(label), state == "ok", state)
    state = module.verify_block(original, BLOCK)
    check("{0}：verify 对未打补丁的文件报 missing".format(label), state == "missing", state)


def main():
    module = _patcher()
    tmp = Path(tempfile.mkdtemp(prefix="afk_patcher_"))
    try:
        _roundtrip(module, "LF 文件", SAMPLE)
        _roundtrip(module, "CRLF 文件", SAMPLE.replace("\n", "\r\n"))
        _roundtrip(module, "无结尾换行", SAMPLE.rstrip("\n"))

        # 行尾跟随：CRLF 文件里插入的补丁块也必须是 CRLF，否则 git diff 一片噪声
        crlf = SAMPLE.replace("\n", "\r\n")
        patched, _ = module.apply_block(crlf, BLOCK)
        bare = patched.count("\n") - patched.count("\r\n")
        check("CRLF 文件里插入的补丁块跟随 CRLF 行尾", bare == 0, "裸 LF 有 {0} 处".format(bare))

        # 原子写：落盘后不留临时文件，内容完整替换
        target = tmp / "atom.py"
        _write(target, SAMPLE)
        module._write(target, SAMPLE + "# tail\n")
        check("原子写：内容完整写入", _read(target) == SAMPLE + "# tail\n")
        leftovers = [p.name for p in tmp.iterdir() if p.name.endswith(".afk-tmp")]
        check("原子写：不残留临时文件", not leftovers, leftovers)

        # 语法守卫：会毁掉文件的补丁被拦住，并且不落盘
        broken_block = {
            "id": "smoke-broken",
            "file": "main.py",
            "anchor": 'input("Error, Enter to exit/错误，回车退出:")',
            # 缩进故意写错，模拟「插入点算错一位」
            "insert": "  sys.exit(1)\n",
        }
        bad_dir = tmp / "guard"
        bad_dir.mkdir()
        bad_file = bad_dir / "main.py"
        _write(bad_file, SAMPLE)
        report = module.cmd_apply(tmp, only=["__none__"])  # 只用它确认 only 过滤不炸
        check("cmd_apply 在 only 无匹配时返回空报告", report == {}, report)
        project_dir = tmp / "GuardProject"
        project_dir.mkdir()
        _write(project_dir / "main.py", SAMPLE)
        original_patches = module.PATCHES
        module.PATCHES = {"GuardProject": {"path": "GuardProject", "blocks": [broken_block]}}
        try:
            report = module.cmd_apply(tmp, ["GuardProject"])
        finally:
            module.PATCHES = original_patches
        states = [state for _, state in report.get("GuardProject", [])]
        check("语法守卫：会毁掉文件的补丁被报成 error",
              any(str(s).startswith("error") for s in states), states)
        after = _read(project_dir / "main.py")
        check("语法守卫：被拦下的补丁不落盘（文件保持原样）", after == SAMPLE)
        ok, _ = _compile_ok(after, "GuardProject/main.py")
        check("语法守卫：磁盘上的文件仍然可编译", ok)

        # 合法补丁走同一条 cmd_apply 路径要能真正写进去
        module.PATCHES = {"GuardProject": {"path": "GuardProject", "blocks": [ENTRY_BLOCK]}}
        try:
            report = module.cmd_apply(tmp, ["GuardProject"])
        finally:
            module.PATCHES = original_patches
        states = [state for _, state in report.get("GuardProject", [])]
        check("cmd_apply：合法补丁报 applied", states == ["applied"], states)
        written = _read(project_dir / "main.py")
        check("cmd_apply：补丁确实写进了文件", "AFK-MONITOR:smoke-entry" in written)
        ok, detail = _compile_ok(written, "GuardProject/main.py")
        check("cmd_apply：写完之后文件仍能编译", ok, detail)

        # 真实项目：现有补丁全部落到位、且对应文件都能编译（防止仓库里的补丁定义漂移）
        real_report = module.cmd_verify(ROOT)
        bad = [(name, item, state) for name, rows in real_report.items() for item, state in rows
               if state not in ("ok",)]
        check("仓库里现有补丁定义全部是 ok（没有 drifted/missing）", not bad, bad)
        for rel in ("March7thAssistant/main.py", "BAAH/main.py", "BAAH/BAAH.py"):
            path = ROOT / rel
            if not path.exists():
                continue
            ok, detail = _compile_ok(_read(path), rel)
            check("{0} 打了补丁仍能编译".format(rel), ok, detail)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    print("PATCHER", "PASS" if not FAILED else "FAIL")
    return 0 if not FAILED else 1


if __name__ == "__main__":
    sys.exit(main())
